#include <vector>
#include <string>
#include <unordered_map>
#include <queue>
#include <algorithm>

using Entry = std::pair<int, std::string>;   // count, word

std::vector<std::string> top_k_frequent(std::vector<std::string> words, int k) {
    std::unordered_map<std::string, int> count;
    for (const auto& w : words) ++count[w];
    // true when a should sit below b, so the worst entry is on top
    auto worse = [](const Entry& a, const Entry& b) {
        if (a.first != b.first) return a.first > b.first;
        return a.second < b.second;
    };
    std::priority_queue<Entry, std::vector<Entry>, decltype(worse)> heap(worse);
    for (const auto& kv : count) {
        heap.push({kv.second, kv.first});
        if ((int)heap.size() > k) heap.pop();
    }
    std::vector<std::string> out(heap.size());
    for (int i = (int)out.size() - 1; i >= 0; --i) {
        out[i] = heap.top().second;
        heap.pop();
    }
    return out;
}

