import heapq

def kth_largest_stream(k, initial, adds):
    heap = []                    # the k largest so far
    for x in initial:
        heapq.heappush(heap, x)
        if len(heap) > k:
            heapq.heappop(heap)
    out = []
    for x in adds:
        heapq.heappush(heap, x)
        if len(heap) > k:
            heapq.heappop(heap)
        out.append(heap[0])      # smallest of the k largest
    return out

